CREATE TABLE IF NOT EXISTS `watchlists` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL)
CREATE TABLE IF NOT EXISTS `instruments` (`listId` INTEGER NOT NULL, `id` TEXT NOT NULL, `ticker` TEXT NOT NULL, `name` TEXT NOT NULL, `type` TEXT NOT NULL, `currency` TEXT NOT NULL, `identitySource` TEXT NOT NULL, `verifiedAt` TEXT NOT NULL, `value` TEXT, `previous` TEXT, `kind` TEXT, `timestamp` TEXT, `quoteSource` TEXT, `delayMinutes` INTEGER, `lastCheck` TEXT, `error` TEXT, `timestampBasis` TEXT NOT NULL, `absoluteThreshold` TEXT, `percentThreshold` TEXT, PRIMARY KEY(`listId`, `id`), FOREIGN KEY(`listId`) REFERENCES `watchlists`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE )
CREATE INDEX IF NOT EXISTS `index_instruments_listId` ON `instruments` (`listId`)
CREATE TABLE IF NOT EXISTS `settings` (`id` INTEGER NOT NULL, `enabled` INTEGER NOT NULL, `interval` INTEGER NOT NULL, `days` TEXT NOT NULL, `start` TEXT NOT NULL, `end` TEXT NOT NULL, `everyCheck` INTEGER NOT NULL, `absoluteThreshold` TEXT NOT NULL, `percentThreshold` TEXT NOT NULL, `providerUrl` TEXT NOT NULL, `theme` TEXT NOT NULL, `freeFeeds` INTEGER NOT NULL, PRIMARY KEY(`id`))
CREATE TABLE IF NOT EXISTS `alerts` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `instrumentId` TEXT NOT NULL, `ticker` TEXT NOT NULL, `name` TEXT NOT NULL, `current` TEXT NOT NULL, `previous` TEXT, `absolute` TEXT, `percent` TEXT, `currency` TEXT NOT NULL, `kind` TEXT NOT NULL, `dataTimestamp` TEXT NOT NULL, `checkedAt` TEXT NOT NULL, `source` TEXT NOT NULL, `delivery` TEXT NOT NULL, `timestampBasis` TEXT NOT NULL)
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT)
